--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE TRIGGER "SBERP"."TRG_TASK_BI" 
BEFORE INSERT ON task
FOR EACH ROW
BEGIN
  IF :NEW.task_id IS NULL THEN
    SELECT seq_task.NEXTVAL INTO :NEW.task_id FROM dual;
  END IF;
END;

